entries[152150] = { ["name"] = "Tod von oben", ["text"] = "25 Energie / 1 zu 5 Combopunkte 15 Meter Reichweite\nSofort 20 sek. Abklingzeit\nBenötigt Einhändige Nahkampfwaffe\nFinishing-Move, der Eure Waffen mit Schattenenergie verstärkt und einen vernichtenden zweiteiligen Angriff ausführt.\n\nIhr wirbelt herum, fügt allen Gegnern innerhalb von 8 Metern (57.33% der Angriffskraft) Schaden zu, springt dann in die Luft und setzt auf dem Weg nach unten [ Vergiften : 'Vergiften' ] [ Tötung : 'Tötung' / 'Ausweiden' ] mit solcher Wucht gegen Euer Ziel ein, dass der Effekt der Fähigkeit um 50% erhöht wird." }
entries[152151] = { ["name"] = "Schattenreflexion", ["text"] = "20 Meter Reichweite\nSofort 2 min Abklingzeit\nBeschwört einen Schatten von Euch selbst auf das Ziel, der Euch beobachtet und sich Euren Einsatz von Offensivfähigkeiten in den nächsten 8 Sek. einprägt. Danach führt der Schatten im Verlauf der folgenden 8 Sek. die eingeprägten Fähigkeiten auf das Ziel aus." }
