entries[152220] = { ["name"] = "Gleichgewicht der Kräfte", ["text"] = "Ihr bringt Euch mit der Kraft des Mondes und der Sterne in Einklang, sodass Eure direkten Schadenszauber Eure regelmäßigen Schadenseffekte mit neuer Energie versorgen.\n\nEuer 'Sternenfeuer' verlängert die Dauer von 'Mondfeuer' um 6 Sek.\nEuer 'Zorn' verlängert die Dauer von 'Sonnenfeuer' um 4 Sek.\n\nErhöht außerdem den regelmäßigen Schaden von 'Mondfeuer' und 'Sonnenfeuer' um 10%." }
