entries[152263] = { ["name"] = "Mächtige Siegel", ["text"] = "Eure Siegel bewirken, dass Euer 'Richturteil' Euch mit einem zusätzlichen positiven Effekt stärkt, der auch nach einem Wechsel des Siegels bestehen bleibt:\n\nRichturteil der Einsicht\nHeilt Euch 21 Sek. lang alle 3 Sek. um 2% Eurer maximalen Gesundheit.\n\nRichturteil der Rechtschaffenheit\nErhöht Euer Angriffstempo 20 Sek. lang um 20%.\n\nRichturteil der Wahrheit\nErhöht Eure Angriffskraft 20 Sek. lang um 15%." }
