entries[152278] = { ["name"] = "Aggressionsmanagement", ["text"] = "Erfordert Level 50 (Waffen, Furor, Schutz)\nSchutz\nPro 10 verbrauchter Wut wird die verbleibende Abklingzeit von 'Avatar' und 'Schildwall' um 1 Sek. verringert.\n\nWaffen\nPro 20 für Angriffe verbrauchter Wut wird die verbleibende Abklingzeit von 'Kolossales Schmettern', 'Klingensturm' und 'Verheerer' um 1 Sek. verringert.\n\nWaffen (Kriegsbrecher)\nPro 20 für Angriffe verbrauchter Wut wird die verbleibende Abklingzeit von 'Kriegsbrecher', 'Klingensturm' und 'Verheerer' um 1 Sek. verringert.\n\nFuror\nPro 20 verbrauchter Wut wird die verbleibende Abklingzeit von 'Tollkühnheit', 'Klingensturm' und 'Verheerer' um 1 Sek. verringert." }
entries[152279] = { ["name"] = "Sindragosas Hauch", ["text"] = "16 Runenmacht pro Sek.\nSofort 2 min Abklingzeit\nFügt Gegnern in einem kegelförmigen Bereich vor Euch kontinuierlich alle 1 Sek. [(139.788% der Angriffskraft) * [(Angriffskraft * 0.98)][((Angriffskraft + Schildhand-Angriffskraft) * 2 / 3)] -- 2H, DW / Angriffskraft] Frostschaden zu, bis Eure Runenmacht aufgebraucht ist. Sekundärziele erleiden weniger Schaden.\n\nErzeugt jeweils 1 Rune zu Beginn und Ende des Fähigkeitseinsatzes." }
entries[152280] = { ["name"] = "Entweihen", ["text"] = "Ersetzt Tod und Verfall\n1 Rune / -10 Runenmacht 30 Meter Reichweite\nSofort 30 sek. Abklingzeit\n1 Aufladung\nEntweiht den anvisierten Boden und fügt allen Gegnern im Verlauf von 10 Sek. [((15% der Angriffskraft) * (11))] Schattenschaden zu.\n\nInnerhalb des Effektbereichs Eures Zaubers 'Entweihen' trefft Ihr mit [ Reißende Schatten : 'Reißende Schatten' / 'Geißelstoß'] 7 Gegner in der Nähe des Ziels .\n\nJede Sekunde vergrößert sich der Effektbereich von 'Entweihen' und der Schaden erhöht sich, wenn sich Gegner innerhalb des Effektbereichs aufhalten." }
entries[152282] = { ["name"] = "Rankenschlag", ["text"] = "Nahkampfreichweite\nWirken in 3 sek. 6 sek. Abklingzeit\nBereitet einen massiven Angriff vor, der nach kurzer Verzögerung den Boden trifft, Naturschaden verursacht und Ziele zurückstößt." }
